.pdb-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.pdb-root,.pdb-root *,.pdb-root *::before,.pdb-root *::after{box-sizing:border-box}
.pdb-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.pdb-root img{display:block;border:0;max-width:none}
.pdb-root > [data-node-id]{will-change:transform}
.pdb-root [hidden]{display:none!important}
.pdb-root [data-sh-theme="dark"]{display:none!important}
.pdb-root[data-theme="dark"] [data-sh-theme="dark"]{display:block!important}
.pdb-root[data-theme="dark"] [data-sh-theme="dark"]{display:none!important}
.pdb-root .n3292_5611{align-content:stretch;display:flex;gap:5px;align-items:center;justify-content:center;padding-left:24px;padding-right:24px;padding-top:15px;padding-bottom:15px;position:relative;border-radius:35px;flex-shrink:0;background-image:linear-gradient(to top, color-mix(in srgb, var(--wa-point, rgb(42 116 244)) 70%, transparent) 3%, var(--wa-point, #2a74f4) 80.244%)}
.pdb-root .n3292_5611::after{content:"";position:absolute;inset:-0px;border:1px solid var(--wa-line, #fff);border-radius:35px;pointer-events:none}
.pdb-root .n3292_5612{position:relative;flex-shrink:0;width:16px;height:16px}
.pdb-root .x152{position:absolute;display:block;inset:0;max-width:none;width:100%;height:100%}
.pdb-root .n3292_5614{word-break:break-word;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:520;line-height:20px;font-style:normal;position:relative;flex-shrink:0;color:var(--wa-text, #f3f9fb);font-size:18px;text-align:center;white-space:nowrap;width:159px}
.pdb-root [data-name^="Card/Stage"] p{letter-spacing:-0.05em;word-break:keep-all}
.pdb-root[data-theme="dark"]{color:var(--wa-point, #e3e9f2)}
.pdb-root[data-theme="dark"] > [data-node-id] > div[aria-hidden] > div{background:linear-gradient(180deg,var(--wa-bg, #0d1117) 0%,var(--wa-bg, #111821) 100%)!important}
.pdb-root[data-theme="dark"] > [data-node-id] > div[aria-hidden] > img{opacity:.04!important;filter:invert(1)}
.pdb-root[data-theme="dark"] [data-name="Stage/3D Scene"] img{filter:brightness(.9) saturate(.95) contrast(1.03)}
.pdb-root[data-theme="dark"] [data-name="Stage/Building Image"] img{filter:brightness(.86) contrast(1.04)}
.pdb-root[data-theme="dark"] [data-name="Side Rail"],.pdb-root[data-theme="dark"] [data-name="Filter Panel"] [data-name="Rectangle 4"]{background:color-mix(in srgb, var(--wa-bg, rgb(20 23 29)) 84%, transparent)!important;box-shadow:0 0 0 1px rgba(255,255,255,.07),0 12px 28px rgba(0,0,0,.35)!important;-webkit-backdrop-filter:blur(14px);backdrop-filter:blur(14px)}
.pdb-root[data-theme="dark"] > [data-node-id] > [data-name="Header"] > [data-name="Background"],.pdb-root[data-theme="dark"] > [data-node-id] > [data-name="Header"] > [data-name="Header Background"]{background:var(--wa-bg, #12151b)!important;box-shadow:inset 0 -1px 0 rgba(255,255,255,.07)!important}
.pdb-root[data-theme="dark"] svg [fill="#FCFCFC"]:not(mask *),.pdb-root[data-theme="dark"] svg [fill="#fcfcfc"]:not(mask *),.pdb-root[data-theme="dark"] svg [fill="white"]:not(mask *),.pdb-root[data-theme="dark"] svg [fill="#F9F9F9"]:not(mask *){fill:var(--wa-surface, #15181e)}
.pdb-root[data-theme="dark"] svg [stroke="#F1F1F1"]:not(mask *),.pdb-root[data-theme="dark"] svg [stroke="#f1f1f1"]:not(mask *),.pdb-root[data-theme="dark"] svg [fill="#F1F1F1"]:not(mask *){stroke:var(--wa-line, #2a2e36)}
.pdb-root[data-theme="dark"] svg path[fill="#F1F1F1"]:not(mask *){fill:var(--wa-surface, #2a2e36)}
.pdb-root[data-theme="dark"] [data-name="Event Log"] [data-name^="Row/"]:hover,.pdb-root[data-theme="dark"] [data-name="Event Log"] [data-name="grid-row"]:hover{filter:brightness(1.15)}
.pdb-root[data-theme="dark"] [data-name="Tooltip Group"] [data-name^="Tooltip/"] p{color:var(--wa-text, #e6ebf2)!important}
